{"command": "cd /home/typhoeus/this && python3 - <<'PY'
import re,os,glob,collections
files=[p for p in glob.glob("Code_Design/**/*.md",recursive=True)]
defined=collections.defaultdict(set)
used=collections.defaultdict(set)
newobj=re.compile(r"^\|\s*(CLS-[A-Z0-9]+-\d+|API-[A-Z0-9]+-\d+)\s*\|")
for p in files:
    for i,l in enumerate(open(p,encoding="utf-8"),1):
        m=newobj.match(l)
        if m: defined[m.group(1)].add(p)
        for i2 in set(re.findall(r"`((?:CLS|API)-[A-Z0-9]+-\d+)`",l)):
            used[i2].add(p)
# 1) duplicates: same ID defined in >1 file
dups={k:v for k,v in defined.items() if len(v)>1}
print("== 同一 ID 在多个文件中作为表首列出现（可能重复定义）==")
for k,v in sorted(dups.items()):
    print(" ",k,"->",[os.path.basename(x) for x in v])
# 2) undefined: used but never defined anywhere
undef=sorted(k for k in used if k not in defined)
print("\n== 被引用但全库无表首定义（含跨库定义，属正常，仅列前 40）==")
print("  共",len(undef))
print("  ",", ".join(undef[:40]))
PY", "description": "Check ID uniqueness and definition coverage"}

