{"command": "cd /home/typhoeus/this && python3 - <<'PY'
import re,glob,os,collections
files=glob.glob("Code_Design/**/*.md",recursive=True)
pats={"CLS-OBJ":r"CLS-OBJ-\d+","API-OBJ":r"API-OBJ-\d+","CLS-SKILLDEF":r"CLS-SKILLDEF-\d+","API-SKILLDEF":r"API-SKILLDEF-\d+","CLS-FIELD":r"CLS-FIELD-\d+","API-FIELD":r"API-FIELD-\d+","CLS-M01":r"CLS-M01-\d+","API-M01":r"API-M01-\d+","I-M01":r"I-M01-\d+","REQ-M01":r"REQ-M01-\d+"}
for name,pat in pats.items():
    ids=set()
    for p in files:
        ids|=set(re.findall(pat,open(p,encoding="utf-8").read()))
    nums=sorted(int(i.rsplit("-",1)[1]) for i in ids)
    missing=[n for n in range(1,max(nums)+1) if n not in nums] if nums else []
    print(f"{name:12s} 共 {len(nums):3d} 个，最大 {max(nums) if nums else 0:3d}，缺号 {missing}")
PY", "description": "Check ID ranges and gaps"}

